package alphametics

import (
	"errors"
	"fmt"
	"strings"
)

var errNoSolution = errors.New("no solution")

func Solve(puzzle string) (map[string]int, error) {
	eq := strings.Split(puzzle, "==")
	if len(eq) != 2 {
		return nil, fmt.Errorf("invalid puzzle: %q", puzzle)
	}
	addends := strings.Split(eq[0], "+")
	for i := range addends {
		addends[i] = strings.TrimSpace(addends[i])
	}
	result := strings.TrimSpace(eq[1])

	// collect letters
	seen := map[rune]bool{}
	leading := map[rune]bool{}
	for _, w := range append(addends, result) {
		for i, r := range w {
			seen[r] = true
			if i == 0 && len(w) > 1 {
				leading[r] = true
			}
		}
	}
	letters := make([]rune, 0, len(seen))
	for r := range seen {
		letters = append(letters, r)
	}
	if len(letters) > 10 {
		return nil, errNoSolution
	}

	// columns
	maxLen := len(result)
	for _, w := range addends {
		if len(w) > maxLen {
			maxLen = len(w)
		}
	}
	// column c: addend letters (rune(0) if absent), result letter
	...
}
```

